'use client';
const require_table = require("./table.cjs");
const require_table_body = require("./table-body.cjs");
const require_table_cell = require("./table-cell.cjs");
const require_table_foot = require("./table-foot.cjs");
const require_table_head = require("./table-head.cjs");
const require_table_header_cell = require("./table-header-cell.cjs");
const require_table_row = require("./table-row.cjs");
//#region src/components/table/index.ts
/**
* Table component, used to display tabular data. Renders a native HTML table element.
*
* @example
* <Table>
*   <Table.Head>
*     <Table.Row>
*       <Table.HeaderCell>Name</Table.HeaderCell>
*       <Table.HeaderCell>Age</Table.HeaderCell>
*     </Table.Row>
*   </Table.Head>
*   <Table.Body>
*     <Table.Row>
*       <Table.Cell>John</Table.Cell>
*       <Table.Cell>25</Table.Cell>
*     </Table.Row>
*   </Table.Body>
*   <Table.Foot>
*     <Table.Row>
*       <Table.Cell>Total</Table.Cell>
*       <Table.Cell>2</Table.Cell>
*     </Table.Row>
*   </Table.Foot>
* </Table>
*/
const TableComponent = Object.assign(require_table.Table, {
	Head: require_table_head.TableHead,
	Body: require_table_body.TableBody,
	Row: require_table_row.TableRow,
	Cell: require_table_cell.TableCell,
	HeaderCell: require_table_header_cell.TableHeaderCell,
	Foot: require_table_foot.TableFoot
});
TableComponent.displayName = "Table";
TableComponent.Head.displayName = "Table.Head";
TableComponent.Body.displayName = "Table.Body";
TableComponent.Row.displayName = "Table.Row";
TableComponent.Cell.displayName = "Table.Cell";
TableComponent.HeaderCell.displayName = "Table.HeaderCell";
TableComponent.Foot.displayName = "Table.Foot";
//#endregion
exports.Table = TableComponent;
exports.TableBody = require_table_body.TableBody;
exports.TableCell = require_table_cell.TableCell;
exports.TableFoot = require_table_foot.TableFoot;
exports.TableHead = require_table_head.TableHead;
exports.TableHeaderCell = require_table_header_cell.TableHeaderCell;
exports.TableRow = require_table_row.TableRow;
